<?php require_once __DIR__.'/../../includes/functions.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)$_POST['name']);$s=db()->prepare('INSERT INTO attractions(destination_id,category_id,name,slug,short_description,description,youtube_url,maps_url,opening_hours,status) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([(int)$_POST['destination_id'],$_POST['category_id']?:null,$name,slug($name),trim((string)$_POST['short_description']),trim((string)$_POST['description']),trim((string)$_POST['youtube_url']),trim((string)$_POST['maps_url']),trim((string)$_POST['opening_hours']),'active']);flash('success','Attraction added.');redirect('index.php');}$rows=db()->query('SELECT a.*,d.name destination_name FROM attractions a JOIN destinations d ON d.id=a.destination_id ORDER BY a.created_at DESC')->fetchAll();$ds=db()->query("SELECT id,name FROM destinations WHERE status='active' ORDER BY name")->fetchAll();$cats=db()->query("SELECT id,name FROM categories WHERE status='active' ORDER BY name")->fetchAll();$title='Attractions';include __DIR__.'/../../includes/header.php';?><main class="container py-5"><h1 class="display-serif">Attractions</h1><div class="card p-4 my-4"><form method="post"><?=csrf_field()?><div class="row g-3"><div class="col-md-4"><label class="form-label">Name<input name="name" class="form-control" required></label></div><div class="col-md-4"><label class="form-label">Destination<select name="destination_id" class="form-select" required><?php foreach($ds as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></label></div><div class="col-md-4"><label class="form-label">Category<select name="category_id" class="form-select"><option value="">None</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label></div><div class="col-md-6"><label class="form-label">Short description<input name="short_description" class="form-control"></label></div><div class="col-md-6"><label class="form-label">Opening hours<input name="opening_hours" class="form-control"></label></div><div class="col-12"><label class="form-label">Description<textarea name="description" class="form-control"></textarea></label></div><div class="col-md-6"><label class="form-label">YouTube URL<input name="youtube_url" class="form-control" type="url"></label></div><div class="col-md-6"><label class="form-label">Maps URL<input name="maps_url" class="form-control" type="url"></label></div></div><button class="btn btn-success mt-3">Add attraction</button></form></div><div class="card p-3"><table class="table"><thead><tr><th>Name</th><th>Destination</th><th>Video</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['destination_name'])?></td><td><?=youtube_id($r['youtube_url'])?'Yes':'—'?></td></tr><?php endforeach;?></tbody></table></div></main><?php include __DIR__.'/../../includes/footer.php';?>
